if (RBC_LBORNR != null && RBC_LBORRES  != null && RBC_LBRANGE != null)
{   var range = parseRangeValue(RBC_LBORNR);
    var res = RBC_LBORRES;
	var resr = RBC_LBRANGE;

	if (range.Comparator == "InclusiveInBetween")
	{
		   if (resr == "3")
	       {
		       if (res > range.Lower)
		       {return false;}
		       else return true;
	       }
	       else if (resr == "2")
	       {
		       if (res < range.Upper)
		       {return false;}
		       else return true;
	       }
	       else if (resr == "1")
	       {
		       if (res >= range.Lower && res <= range.Upper)
		       {return false;}
		       else return true;
	       }
	      else return false;
	}

	else if (range.Comparator == "LessThan" && (resr == "2" || resr == "1"))
	{
			  if (res < range.Upper)
		      {return false;}
		      else return true;		
	}

	else if (range.Comparator == "LessThanOrEqualTo")
	{
		   if (resr == "2")
	       {
		       if (res < range.Upper)
		       {return false;}
		       else return true;
	       }
		   if (resr == "1")
	       {
		       if (res <= range.Upper)
		       {return false;}
		       else return true;
	       }
           else return false;
	}

    else if (range.Comparator == "GreaterThan" && (resr == "1" || resr == "3"))
	{
   			   if (res > range.Lower)
		       {return false;}
		       else return true;		   
	}

	else if (range.Comparator == "GreaterThanOrEqualTo")
	{
		   if (resr == "1")
	       {
		        if (res >= range.Lower)
		        {return false;}
		        else return true;
	       }
		   if (resr == "3")
	       {
		        if (res > range.Lower)
		        {return false;}
		        else return true;
	       }
	       else return false;
	}

	else if (range.Comparator == "EqualTo" && resr == "1")
	{
		   if (res == range.Lower)
		   {return false;}
		   else return true;
	}
	else if (range.Comparator == "EqualTo" && resr != null && resr != "1")
	{
		return true;
	}

	else return false;
}
else return false;

